<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class GoodsReceipt extends Model { protected $fillable=['mrr_no','mrr_date','payment_mode','cash_head','cash_account_id','purchase_type','currency','exchange_rate','store_id','supplier_id','po_no','remarks','total_amount','paid_amount','user_id']; protected function casts():array{return ['mrr_date'=>'date','total_amount'=>'decimal:2','paid_amount'=>'decimal:2'];} public function items():HasMany{return $this->hasMany(GoodsReceiptItem::class);} public function supplier():BelongsTo{return $this->belongsTo(Supplier::class);} public function cashAccount():BelongsTo{return $this->belongsTo(ChartOfAccount::class,'cash_account_id');} public function getDueAttribute():string{return number_format(max(0,(float)$this->total_amount-(float)$this->paid_amount),2,'.','');} }
